INSERT INTO `wpfd_addonlibrary_addons` (`id`, `title`, `name`, `alias`, `addontype`, `description`, `ordering`, `templates`, `config`, `catid`, `is_active`, `test_slot1`, `test_slot2`, `test_slot3`) VALUES
(1, 'Cookie Consent', 'cookie_consent_elementor', 'cookie_consent', 'elementor', 'Cookie Consent widget ensures privacy compliance by displaying a banner about cookie usage. It allows users to accept or manage cookie preferences, enhancing trust.', 1, '{\"html\":\"<div id=\\\"{{uc_id}}\\\" class=\\\"ue-cookie-consent-wrapper\\\">\\n  {% if uc_inside_editor == \\\"yes\\\" %}\\n    <div class=\\\"ue-cookie-consent-added\\\">Cookie Consent widget Added to the Page. This Message shows only in Editor.<\\/div>\\n  {% endif %}\\t\\n  \\n   <div class=\\\"ue-cookie-consent\\\" style=\\\"display:none;\\\">\\n     \\n      <div class=\\\"ue-cookie-desc-wrapper\\\">\\n        {% if show_title == \\\"true\\\" %}<div class=\\\"ue_cookie_title\\\">\\n            {% if show_icon == \\\"true\\\" %}<div class=\\\"ue_cookie_icon\\\">{{icon_html|raw}}<\\/div>{% endif %}\\n            {{title|raw}}<\\/div>\\n        {% endif %}\\n        {% if show_description == \\\"true\\\" %}<div class=\\\"ue_cookie_desc\\\">{{consent_message|raw}}<\\/div>{% endif %}\\n      <\\/div>\\n\\n      <div class=\\\"ue-cookie-button-wrapper\\\">\\n        {% if compliance_type == \\\"notify\\\" %}\\n          <div class=\\\"ue-cookies-button ue-confirm-cookies\\\" area-label=\\\"{{confirm_button_text}}\\\" role=\\\"button\\\">{{confirm_button_text|raw}}<\\/div>\\n        {% endif %}\\n        {% if compliance_type == \\\"permission\\\" %}\\n          <div class=\\\"ue-cookies-button ue-accept-cookies\\\" area-label=\\\"{{accept_button_text}}\\\" role=\\\"button\\\">{{accept_button_text|raw}}<\\/div>\\n          <div class=\\\"ue-cookies-button ue-reject-cookies\\\" area-label=\\\"{{reject_button_text}}\\\" role=\\\"button\\\">{{reject_button_text|raw}}<\\/div>\\n        {% endif %}\\n      <\\/div>\\n      {% if show_close_button == \\\"true\\\" %}<div class=\\\"ue-cookie-close\\\">{{close_icon_html|raw}} {{close_text|raw}}<\\/div>{% endif %}\\n   <\\/div>\\n<\\/div>\",\"css\":\"#{{uc_id}}{\\n  display: flex;\\n  justify-content: center;\\n  min-height: 1px;\\n} \\n\\n\\/* message in editor styles *\\/\\n#{{uc_id}} .ue-cookie-consent-added{\\n  padding: 10px;\\n  border: 1px solid grey;\\n  background-color: lightgrey;\\n  border-radius: 5px;\\n  font-size: 12px;\\n}\\n\\/* end message in editor styles *\\/\\n\\n#{{uc_id}} *{\\n  box-sizing: border-box;\\n}\\n\\n#{{uc_id}} .ue-cookie-desc-wrapper{\\n  display: flex;\\n}\\n\\n#{{uc_id}} .ue-cookie-consent {\\n  display:flex;\\n  {% if (uc_inside_editor == \\\"yes\\\") and (debug_consent_popup == \\\"true\\\") %}\\n  display:flex !important;\\n  {% endif %}\\n}\\n\\n{% if (show_description == \\\"true\\\") and (title_position == \\\"row\\\") %}\\n  #{{uc_id}} .ue_cookie_desc{\\n    display: flex;\\n    align-items: center;\\n    gap:5px;\\n  }\\n{% endif %}\\n\\n#{{uc_id}} .ue-cookie-button-wrapper{\\n  display:flex;\\n}\\n\\n#{{uc_id}} .ue-cookies-button{\\n  cursor: pointer;\\n  text-align:center;\\n}\\n\\n{% if show_close_button == \\\"true\\\" %}\\n  #{{uc_id}} .ue-cookie-close{\\n    position:absolute;\\n    right:0;\\n    top:0;\\n    cursor:pointer;\\n    line-height: 1;\\n  }\\n\\n  #{{uc_id}} .ue-cookie-close i, \\n  #{{uc_id}} .ue-cookie-close svg{\\n    pointer-events: none;\\n  }\\n\\n  #{{uc_id}} .ue-cookie-close svg{\\n    width:1em;\\n    height:1em;\\n  }\\n{% endif %}\\n\\n{% if show_icon == \\\"true\\\" %}\\n  #{{uc_id}} .ue_cookie_icon{\\n    line-height: 1;\\n  }\\n\\n  #{{uc_id}} .ue_cookie_icon svg{\\n    width:1em;\\n    height:1em;\\n  }\\n{% endif %}\\n\\n{% if show_icon == \\\"true\\\" %}\\n  #{{uc_id}} .ue_cookie_title{\\n    display:flex;\\n    {% if icon_position == \\\"row\\\" %}\\n    align-items: center;\\n    {% endif %}\\n  }\\n{% endif %}\",\"js\":\"jQuery(document).ready(function() {\\n    var ueCookieConsent = jQuery(\\\"#{{uc_id}} .ue-cookie-consent\\\");\\n    var cookieName = \\\"ue_cookie_consent\\\";\\n    var cookieValue = \\\"accepted\\\";\\n    var choiceMadeName = \\\"ue_cookie_choice_made\\\";\\n    var choiceMadeValue = \\\"yes\\\";\\n    var expirationDays = 365;\\n    var complianceType = \\\"{{compliance_type}}\\\"; \\/\\/ Get the compliance type\\n    var isDemoMode = \\\"{{demo_mode}}\\\";\\n\\n    function setCookie(name, value, days) {\\n        var expires = \\\"\\\";\\n        if (days) {\\n            var date = new Date();\\n            date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));\\n            expires = \\\"; expires=\\\" + date.toUTCString();\\n        }\\n        document.cookie = name + \\\"=\\\" + (value || \\\"\\\") + expires + \\\"; path=\\/\\\";\\n    }\\n\\n    function getCookie(name) {\\n        var nameEQ = name + \\\"=\\\";\\n        var ca = document.cookie.split(\';\');\\n        for (var i = 0; i < ca.length; i++) {\\n            var c = ca[i];\\n            while (c.charAt(0) == \' \') c = c.substring(1, c.length);\\n            if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length, c.length);\\n        }\\n        return null;\\n    }\\n\\n    function eraseCookie(name) {\\n        document.cookie = name + \'=; Max-Age=-99999999;\';\\n    }\\n\\n    function hideConsent() {\\n        ueCookieConsent.hide();\\n    }\\n\\n    function showConsent() {\\n        ueCookieConsent.css(\\\"display\\\", \\\"flex\\\");\\n    }\\n\\n    function acceptCookies() {\\n        if(isDemoMode == \\\"false\\\"){\\n        \\tsetCookie(cookieName, cookieValue, expirationDays);\\n        \\tsetCookie(choiceMadeName, choiceMadeValue, expirationDays);\\n        }\\n        \\n        hideConsent();\\n    }\\n\\n    function rejectCookies() {      \\n        if(isDemoMode == \\\"false\\\"){\\n        \\tdocument.cookie.split(\\\";\\\").forEach(function(c) { \\n              document.cookie = c.replace(\\/^ +\\/, \\\"\\\").replace(\\/=.*\\/, \\\"=;expires=\\\" + new Date().toUTCString() + \\\";path=\\/\\\"); \\n            });\\n\\n            Object.defineProperty(document, \'cookie\', {\\n              get: function() { return \'\'; },\\n              set: function() { return true; }\\n            });\\n        }\\n        \\n        hideConsent();\\n    }\\n\\n    \\/\\/ Check if user has already made a choice\\n    if (getCookie(choiceMadeName) === choiceMadeValue && isDemoMode == \\\"false\\\") {\\n        hideConsent();\\n    } else {\\n        showConsent();\\n    }\\n\\n    \\/\\/ Event listeners\\n    if (complianceType === \\\"notify\\\") {\\n        ueCookieConsent.find(\'.ue-confirm-cookies\').on(\'click\', function() {\\n            acceptCookies();\\n        });\\n    } else if (complianceType === \\\"permission\\\") {\\n        ueCookieConsent.find(\'.ue-accept-cookies\').on(\'click\', function() {\\n            acceptCookies();\\n        });\\n        ueCookieConsent.find(\'.ue-reject-cookies\').on(\'click\', function() {\\n            rejectCookies();\\n        });\\n    }\\n\\n    ueCookieConsent.find(\'.ue-cookie-close\').on(\'click\', function() {\\n        if (complianceType === \\\"notify\\\") {\\n            acceptCookies(); \\/\\/ In notify mode, closing is equivalent to accepting\\n        } else {\\n            hideConsent(); \\/\\/ In permission mode, just hide without making a choice\\n        }\\n    });\\n});\"}', '{\"options\":{\"enable_items\":\"\",\"path_assets\":\"ue_cookie_consent\",\"js_as_module\":false,\"addon_icon\":\"\",\"dynamic_addon\":\"false\",\"dynamic_post_enable_customfields\":\"false\",\"dynamic_post_enable_category\":\"false\",\"description\":\"Cookie Consent widget ensures privacy compliance by displaying a banner about cookie usage. It allows users to accept or manage cookie preferences, enhancing trust.\",\"link_resource\":\"\",\"link_preview\":\"https:\\/\\/unlimited-elements.com\\/cookie-consent-widget-for-elementor\\/\",\"show_small_icon\":\"true\",\"preview_size\":\"full\",\"preview_custom_width\":\"\",\"preview_bgcol\":\"#ffffff\",\"special\":\"\",\"special_data\":\"\",\"is_free_addon\":true,\"is_new_addon\":false,\"is_trending\":false},\"params\":[{\"type\":\"uc_dropdown\",\"title\":\"Compliance Type\",\"name\":\"compliance_type\",\"description\":\"Notify User: Just notify users that the site uses cookies<br>\\nAsk User: Ask users to opt into cookies\",\"enable_condition\":false,\"condition_attribute\":\"\",\"condition_operator\":\"equal\",\"condition_value\":[],\"condition_attribute2\":\"\",\"condition_operator2\":\"equal\",\"condition_value2\":null,\"label_block\":false,\"tabname\":\"\",\"options\":{\"Notify User\":\"notify\",\"Ask User\":\"permission\"},\"default_value\":\"notify\",\"pro_options\":[\"permission\"],\"is_pro\":true,\"selector\":\"\",\"selector_value\":\"\",\"show_more_selectors\":false,\"selector2\":\"\",\"selector2_value\":\"\",\"selector3\":\"\",\"selector3_value\":\"\",\"is_responsive\":false,\"default_value_tablet\":\"\",\"default_value_mobile\":\"\",\"php_filter_name\":\"\",\"__attr_catid__\":\"cat_general_general\"},{\"type\":\"uc_radioboolean\",\"title\":\"Show Title\",\"name\":\"show_title\",\"description\":\"\",\"enable_condition\":false,\"condition_attribute\":\"\",\"condition_operator\":\"equal\",\"condition_value\":[],\"condition_attribute2\":\"\",\"condition_operator2\":\"equal\",\"condition_value2\":null,\"label_block\":false,\"tabname\":\"\",\"default_value\":\"true\",\"true_name\":\"Yes\",\"true_value\":\"true\",\"false_name\":\"No\",\"false_value\":\"false\",\"is_responsive\":false,\"default_value_tablet\":\"\",\"default_value_mobile\":\"\",\"__attr_catid__\":\"cat_content_61bb7tfi\"},{\"type\":\"uc_textfield\",\"title\":\"Title\",\"name\":\"title\",\"description\":\"\",\"enable_condition\":true,\"condition_attribute\":\"show_title\",\"condition_operator\":\"equal\",\"condition_value\":[\"true\"],\"condition_attribute2\":\"\",\"condition_operator2\":\"equal\",\"condition_value2\":null,\"label_block\":false,\"tabname\":\"\",\"default_value\":\"Cookie Notice!\",\"font_editable\":false,\"placeholder\":\"\",\"disable_dynamic\":false,\"__at