INSERT INTO `wpfd_addonlibrary_addons` (`id`, `title`, `name`, `alias`, `addontype`, `description`, `ordering`, `templates`, `config`, `catid`, `is_active`, `test_slot1`, `test_slot2`, `test_slot3`) VALUES
(6, 'WordPress Menu', 'nav_menu_elementor', 'nav_menu', 'elementor', 'The WordPress Menu widget helps you create navigation menus for Elementor websites, offering advanced styling options and mobile-friendly features for quick multi-level menus.', 1, '{\"html\":\"<div id=\\\"{{uc_id}}\\\" class=\\\"ue-nav-menu ue-{{menu_open_side}}-close\\\" data-show-icons=\\\"{{show_expand_collapse_icons}}\\\" data-breakpoint=\\\"{{responsive_breakpoint}}\\\" data-full-width=\\\"{{full_width_on_mobile}}\\\" data-effect-style=\\\"{{styles}}\\\" data-behaviour=\\\"{{responsive_behaviour}}\\\">\\n  \\n  {% if show_back_link_icon == \\\"true\\\" %}\\n    <div class=\\\"ue-nav-menu-back-link-icon\\\" style=\\\"display: none\\\">{{back_link_icon_html|raw}}<\\/div>\\n  {% endif %}\\n  \\n  <div class=\\\"ue-nav-menu-mobile-wrapper\\\">\\n    <label class=\\\"ue-nav-menu-mobile\\\" for=\\\"mobile_menu{{uc_id}}\\\">\\n      <span class=\\\"ue-nav-menu-mobile-icon-open\\\">{{mobile_icon_html|raw}}<\\/span>\\n      <span class=\\\"ue-nav-menu-mobile-icon-close\\\">{{mobile_icon_close_html|raw}}<\\/span>\\n    <\\/label>\\n  <\\/div>  \\n  \\n  <input id=\\\"mobile_menu{{uc_id}}\\\" class=\\\"ue-nav-menu-checkbox\\\" type=\\\"checkbox\\\">\\n  \\n  {% if show_overlay == \\\"true\\\" and responsive_behaviour == \\\"slide\\\" %}<div class=\\\"ue-nav-menu_overlay\\\"><\\/div>{% endif %}\\n  \\n  {% if responsive_behaviour == \\\"slide\\\" %}\\n    <div class=\\\"ue-nav-menu-side-wrapper\\\">\\n      <div class=\\\"uc-close-side-menu\\\">{{close_button_icon_html|raw}}<\\/div>\\n  {% endif %}\\n  \\n    {{menu|raw}}\\n      \\n  {% if responsive_behaviour == \\\"slide\\\" %}\\n    <\\/div>\\n  {% endif %}\\n  \\n  <div class=\\\"ue-nav-menu-icons-holder\\\" style=\\\"display: none;\\\">\\n    <span class=\\\"ue-nav-menu-icon-expand\\\">{{expand_icon_html|raw}}<\\/span>\\n    <span class=\\\"ue-nav-menu-icon-collapse\\\">{{collapse_icon_html|raw}}<\\/span>\\n    <span class=\\\"ue-nav-menu-icon-first-level-expand\\\">{{first_level_expand_icon_html|raw}}<\\/span>\\n  <\\/div>\\n  \\n<\\/div>\",\"css\":\"\\/* reset defaults *\\/\\ndd, dl, dt, li, ol, ul{\\n  border: unset;\\n  padding: unset;\\n  background: unset;\\n}\\n\\/* end reset defaults *\\/\\n\\n#{{uc_id}}{\\n\\tposition: relative;\\n}\\n\\n#{{uc_id}} .ue-nav-menu-mobile-wrapper{\\n \\tdisplay: flex;\\n}\\n\\n#{{uc_id}} .ue-menu{\\n    display:flex;\\n    list-style:none;\\n    margin:0;\\n    position:relative;\\n  \\tjustify-content:{{align}};\\n}\\n\\n#{{uc_id}} a{\\n  \\tposition: relative;\\n\\ttext-decoration: none;\\n \\tdisplay: flex;\\n  \\talign-items: center;  \\n}\\n\\n{% if styles == \\\"no-hover-effects\\\" %}\\n  #{{uc_id}} a:after,\\n  #{{uc_id}} a:before{\\n      content: \\\"\\\";\\n      z-index: 2;\\n      position:absolute;\\n  }\\n{% endif %}\\n\\n{% if pointer == \\\"underline\\\" %}\\n    #{{uc_id}} a:hover:after,\\n\\t#{{uc_id}} a.uc-active:after{\\n        bottom: 0;\\n        height: 3px;\\n        width: 100%;\\n        left: 0;\\n        background-color: {{pointer_color}};\\n    }  \\n{% endif %}\\t\\n\\n{% if pointer == \\\"overline\\\" %}\\n  \\t#{{uc_id}} a:hover:before,\\n\\t#{{uc_id}} a.uc-active:before{\\n      top: 0;\\n      height: 3px;\\n      width: 100%;\\n      left: 0;\\n      background-color: {{pointer_color}};\\n  \\t}\\n{% endif %}\\n\\n\\n{% if pointer == \\\"double\\\" %}\\n  \\t#{{uc_id}} a:hover:after,\\n\\t#{{uc_id}} a.uc-active:after{\\n      bottom: 0;\\n      height: 3px;\\n      width: 100%;\\n      left: 0;\\n      background-color: {{pointer_color}};\\n    }  \\n  \\t#{{uc_id}} a:hover:before,\\n\\t#{{uc_id}} a.uc-active:before{\\n      top: 0;\\n      height: 3px;\\n      width: 100%;\\n      left: 0;\\n      background-color: {{pointer_color}};\\n  \\t}\\n{% endif %}\\n\\n\\n{% if pointer == \\\"framed\\\" %}\\n  \\t#{{uc_id}} a:hover:before,\\n\\t#{{uc_id}} a.uc-active:before{\\n      top: 0;\\n      bottom:0;\\n      left:0;\\n      right:0;\\n      height: 100%;\\n      width: 100%;\\n      border-style:solid;\\n      border-width:3px;\\n      border-color:{{pointer_color}};\\n  \\t}\\n{% endif %}\\n\\n#{{uc_id}} .ue-menu > li {\\n\\tdisplay: block;\\n  \\t{% if align == \\\"stretch\\\" %}\\n  \\t\\tflex-grow: 1;\\n  \\t{% else %}\\n       flex-shrink: 1;\\n   \\t   min-width: 0;\\n  \\t{% endif %}\\n}\\n\\n\\/* Simple multilevel dropdown *\\/\\n#{{uc_id}} .ue-menu > li > .sub-menu {\\n\\topacity: 0;\\n\\tvisibility: hidden;\\n\\tposition: absolute;\\n\\tlist-style: none;\\n\\ttext-align: inherit;\\n    display:block;\\n\\tz-index: 99;\\n}\\n\\n\\/* First level appear *\\/\\n#{{uc_id}} .ue-menu > li:hover > .sub-menu{\\n\\topacity: 1;\\n\\tvisibility: visible;\\n}\\n\\n#{{uc_id}} .ue-menu > li.uc-active > .sub-menu {\\n\\topacity: 1;\\n\\tvisibility: visible;\\n}\\n\\n\\/* Style for dropdown links *\\/\\n#{{uc_id}} .ue-menu li > .sub-menu li {\\n\\tposition: relative;\\n\\tdisplay: block;\\n}\\n\\n\\/* Second and third dropdown level *\\/\\n#{{uc_id}} .ue-menu > li > .sub-menu li{\\n  display: block;\\n}\\n\\n#{{uc_id}} .ue-menu > li > .sub-menu > li .sub-menu {\\n\\topacity: 0;\\n\\tvisibility: hidden;\\n\\tposition: absolute;\\n\\tlist-style: none;\\n\\ttop:0px;\\n  \\tz-index: 100;\\n}\\n\\n\\/* Second and third level appears *\\/\\n#{{uc_id}} .ue-menu > li .sub-menu li:hover > .sub-menu {\\n\\topacity: 1;\\n\\tvisibility: visible;\\n}\\n\\n#{{uc_id}} .ue-menu > li .sub-menu li.uc-active > .sub-menu {\\n\\topacity: 1;\\n\\tvisibility: visible;\\n}\\n\\n#{{uc_id}} li,\\n#{{uc_id}} a{\\n\\ttransition: all 0.3s ease-in-out;\\n}\\n\\n#{{uc_id}} ul{\\n\\ttransition: all 0.3s ease-in-out;\\n}\\n\\n#{{uc_id}} .ue-nav-menu-checkbox{ \\n  \\tdisplay: none; \\n}\\n\\n#{{uc_id}} .ue-nav-menu-mobile{\\n  \\tdisplay: none;\\n\\ttransition: all .3s;\\n    cursor: pointer;\\n}\\n\\n#{{uc_id}} .ue-nav-menu-icon,\\n#{{uc_id}} .ue-back-link-icon{\\n\\tdisplay: flex;\\n    transition: all .3s ease;\\n}\\n\\n#{{uc_id