 = \'menu-item-has-children\';\\n  var backLinkClass = \\\"ue-back-link\\\";\\n  var openClass = \\\"ue-{{menu_open_side}}-open\\\";\\n  var closeClass = \\\"ue-{{menu_open_side}}-close\\\";\\n  \\n  \\/\\/selectors\\n  var menuItemSelector = \'.\'+hasChildrenClass;\\n  var iconsSelector = \'.ue-nav-menu-icon\';\\n  var subMenuSelector = \'.sub-menu\';\\n  var linkSelector = \'> a\';\\n  \\n  \\/\\/data attributes\\n  var g_showIcons = g_objMenu.data(\'show-icons\');\\n  var dataCustomBreakpoint = g_objMenu.data(\'breakpoint\');\\n  var dataBehaviour = g_objMenu.data(\'behaviour\');\\n  var clickableParents = {{clickable_parent_items}};\\n  var closeOnBodyClick = {{close_on_body_click}};\\n  \\n  \\/\\/html elements\\n  var g_expandIconHtml = objExpandIcon.html();  \\t\\n  \\n  \\/\\/window width\\n  var g_viewportWidth = jQuery(window).width();\\n  var g_isResponsiveViewport = window.matchMedia(\\\"(max-width: \\\"+dataCustomBreakpoint+\\\"px)\\\");\\n  \\n  function setHoverEffects(){  \\n    var dataEffect = g_objMenu.data(\\\"effect-style\\\");\\n    \\n    if(dataEffect == \\\"no-hover-effects\\\")\\n    return(false);\\n    \\n    if(!g_objMenuLinks)\\n    return(false);\\n    \\n    g_objMenuLinks.each(function(){    \\n    \\tvar objLink = jQuery(this);\\n      \\tvar objParent = objLink.parent();\\n      \\n        objParent.addClass(dataEffect);\\n      \\n      \\tvar objLinkText = objLink.text();\\n      \\n      \\tobjLink.attr(\\\"data-hover\\\", objLinkText);\\n    });\\n  }\\n    \\n  function isClickedItemOnFirstLevel(objIcon){    \\n    var firstLevelIconClass = \'uc-first-level-item\';\\n    \\n    \\/\\/check if clicked itcon is not first level icon\\n    var objFirstLevelIcons = g_objFirstLevelMenuItems.find(linkSelector).find(iconsSelector);\\n    \\n    objFirstLevelIcons.addClass(firstLevelIconClass);\\n    \\n    if(objIcon.hasClass(firstLevelIconClass) == true)\\n    return(true);\\n    else\\n    return(false);    \\n  }\\n  \\n  function setActiveIcon(objClicked){    \\n    if(g_showIcons == false)\\n    return(false);\\n    \\n    if(objClicked.hasClass(g_classActive) == false)\\n    return(false);\\n    \\n    var objIcon = objClicked.find(iconsSelector);    \\n    var collapseIconHtml = g_objMenu.find(\'.ue-nav-menu-icon-collapse\').html();\\n    \\n    if(isClickedItemOnFirstLevel(objIcon) == true)\\n    return(false);  \\n    console.log(g_objMenu)\\n    objIcon.html(collapseIconHtml);    \\n  }\\n  \\n  function setDisactiveIcon(objClicked){    \\n    if(g_showIcons == false)\\n    return(false);\\n    \\n    var objIcon = objClicked.find(iconsSelector);\\n    \\n    if(isClickedItemOnFirstLevel(objIcon) == true)\\n    return(false);  \\n    \\n    objIcon.html(g_expandIconHtml);    \\n  }\\n  \\n  function cancelFullWidth(objMobileMenu){    \\n    objMobileMenu.css({\\n      \'width\': \'\',\\n      \'left\': \'\'\\n    });    \\n  }\\n  \\n  function setMenuToFullWidth(objMobileMenu){    \\n    var dataFullWidth = g_objMenu.data(\'full-width\');\\n    \\n    if(dataFullWidth == false || dataBehaviour == \\\"slide\\\")\\n    return(false);\\n    \\n    \\/\\/if not mobile viewport - cancel full width and exit function\\n    if(g_isResponsiveViewport.matches == false){        \\n      cancelFullWidth(objMobileMenu);\\n      return(false);          \\n    }      \\t\\n    \\n    \\/\\/set width to full\\n    objMobileMenu.css(\'width\', g_viewportWidth+\'px\');\\n    \\n    \\/\\/set left position\\n    var menuLeftPosition = g_objMenu.offset().left;\\n    \\n    objMobileMenu.css(\'left\', -menuLeftPosition+\'px\');    \\n  }\\n  \\n  function initResponsiveMode(isResize){    \\n    var objSubMenus = g_objMenu.find(subMenuSelector);\\n    var objMobileMenu = g_objMenu.find(\'.ue-menu\');\\n    var mobileClass = \'uc-mobile\';\\n    var wordpressMenuClass = \\\"uc-wp-menu-mode\\\";\\n    \\n    \\/\\/update viewport width value\\n    g_viewportWidth = jQuery(window).width();      \\n    \\n    \\/\\/set full width if needed\\n    setTimeout(function(){\\n      setMenuToFullWidth(objMobileMenu);\\n    },200);\\n    \\n    if(g_isResponsiveViewport.matches == false){\\n      \\n      \\/\\/remove mobile class from menu\\n      objMobileMenu.removeClass(mobileClass);\\n      jQuery(\'body\').removeClass(wordpressMenuClass);\\n      \\n      if(!isResize || isResize == false)\\n      objSubMenus.slideDown(300);    \\n      \\n      var objLinks = objSubMenus.prev();\\n      \\n      correctOpenMenuPosition(objLinks);      \\n    }        \\n    \\n    if(g_isResponsiveViewport.matches == true){      \\n      \\/\\/add mobile class to menu\\n      objMobileMenu.addClass(mobileClass);\\n      jQuery(\'body\').addClass(wordpressMenuClass);\\n      \\n      if(!isResize && dataBehaviour != \\\"slide\\\" || isResize == false && dataBehaviour != \\\"slide\\\")\\n      objSubMenus.slideUp(300);\\n      \\n      \\/\\/slide up all sub menus after entering responsive breakpoint\\n      if(isResize == true && dataBehaviour != \\\"slide\\\")\\n      objSubMenus.slideUp(300);\\n      \\n      if(g_objBurger.hasClass(g_classActive) == true){\\n        \\n        g_objOpenBurgerIcon.removeClass(g_classActive);\\n        g_objCloseBurgerIcon.addClass(g_classActive);\\n        \\n      }else{\\n        \\n        g_objOpenBurgerIcon.addClass(g_classActive);\\n        g_objCloseBurgerIcon.removeClass(g_classActive);\\n        \\n      }      \\n    }   \\n  }\\n  \\n  \\/*\\n  *\\tcorrect menu item position when there is no space inside viewport\\n  *\\/\\n  function correctOpenMenuPosition(objTarget){      \\n    \\/\\/only on desktop\\n    if(g_isResponsiveViewport.matches == true)\\n    return(false);\\n    \\n    var objSubMenu = objTarget.next();\\n    \\n    \\/\\/ if no sub menus return \\n    if(!objSubMenu.length)\\n    return(false);\\n    \\n    var objParentSubMenus = objTarget.parents(subMenuSelector);\\n    \\n    \\/\\/search only from second level menu items\\n    if(!objParentSubMenus.length)\\n    return(false);  \\n    \\n    \\/\\/each parent submenu\\n    objParentSubMenus.each(function(parentIndex, parent){      \\n      var objParentSubMenu = jQuery(this);\\n      \\n      \\/\\/ Get the position of the menu item relative to the viewport\\n      var objChildSubMenus = objParentSubMenu.find(\'li >\'+subMenuSelector);\\n      \\n      if(!objChildSubMenus.length)\\n      return(true);\\n      \\n      \\/\\/each child submenu\\n      objChildSubMenus.each(function(childIndex, child){        \\n        var objChildSubMenu = jQuery(this);        \\n        \\n        \\/\\/width of the child\\n        var menuItemChildWidth = objChildSubMenu.width();\\n        \\n        \\/\\/width of the parent\\n        var menuItemParentWidth = objParentSubMenu.width();\\n        \\n        \\/\\/right offset of the parent\\n        var menuItemRightOffset = objParentSubMenu.offset().left + menuItemParentWidth;\\n        var menuItemLeftOffset = objParentSubMenu.offset().left;\\n        \\n        \\/\\/ Get the available space on both sides of the screen\\n        var spaceRight = window.innerWidth - menuItemRightOffset;\\n        \\n        \\/\\/get inset-inline-start value\\n        var insetInlineStart = objChildSubMenu.css(\'inset-inline-start\');        \\n        \\n        \\/\\/ if there is NOT enough room (left or right) then invert insert-inline-start \\n        if (menuItemChildWidth >= spaceRight || menuItemChildWidth >= menuItemLeftOffset)\\n        objChildSubMenu.css(\'inset-inline-start\', \'-\'+insetInlineStart);\\n        \\n        \\/\\/ if there is NOT enough room anywhere\\n        if (menuItemChildWidth >= spaceRight && menuItemChildWidth >= menuItemLeftOffset){          \\n          console.log(\'Can\\\"t correct position of the dropdown, please adjust width of menu items\');          \\n          return(true);          \\n        }      \\n        \\n        \\/\\/if there is enough room then cancel invert insert-inline-start\\n        if (menuItemChildWidth < spaceRight && childIndex != parentIndex){          \\n          \\/\\/menuItemChildWidth x2 times because its equal to inset-inline-start\\n          var childSubMenuOffsetRight = objParentSubMenu.offset().left + menuItemParentWidth + menuItemChildWidth + menuItemChildWidth; \\n      \\n          \\/\\/cancel when child sub-menu offset right is not grater then viewport width (must check if after canceling won\'t be any horizontal scroll)     \\n          if(childSubMenuOffsetRight < window.innerWidth)\\n          objChildSubMenu.css(\'inset-inline-start\', \'\');\\n        }                \\n      });      \\n    });    \\n  }\\n  \\n  \\/*\\n  * responsive mode menu item click\\n  *\\/  \\n  function onMenuLinkClick(e, objLink){    \\n    if(g_isResponsiveViewport.matches == false)\\n    return(true);\\n    \\n    var objSubMenu = objLink.next();\\n   \\n    \\/\\/if click on active item then close it\\n    if(objLink.hasClass(g_classActive) == true){      \\n      setDisactiveIcon(objLink);\\n      \\n      if(dataBehaviour != \\\"slide\\\")\\n      objSubMenu.slideUp(300);\\n      \\n      objLink.removeClass(g_classActive);\\n      \\n      return(true);      \\n    }   \\n    \\n    var objSubMenusParent = objSubMenu.parents(subMenuSelector);      \\t\\n    var objSubMenusNotParents = g_objMenu.find(subMenuSelector).not(objSubMenusParent);    \\n    var objMenuLinksParent = objLink.parents(subMenuSelector).prev();\\n    var objMenuLinksNotParents = g_objMenu.find(\'a\').not(objMenuLinksParent);\\n    \\n    objMenuLinksNotParents.removeClass(g_classActive);\\n    objLink.addClass(g_classActive);\\n    \\n    setDisactiveIcon(objMenuLinksNotParents);\\n    setActiveIcon(objLink);        \\n    \\n    if(dataBehaviour != \\\"slide\\\"){\\n      objSubMenusNotParents.slideUp(300);\\n      objSubMenu.slideDown(300);\\n    }      \\n    \\n    if(objSubMenu.length > 0)\\n    e.preventDefault();   \\n  }\\n  \\n  function onMenuInnerItemMouseover(e){    \\n    if(g_isResponsiveViewport.matches == true)\\n    return(false);\\n    \\n    var objHovered = jQuery(this);    \\n    var objItem = objHovered.find(linkSelector);\\n    \\n    setTimeout(function(){\\n      setActiveIcon(objItem);\\n    },100);  \\n    \\n    var objTarget = jQuery(e.target);\\n    correctOpenMenuPosition(objTarget);\\n  }\\n  \\n  function onMenuInnerItemMouseLeave(){    \\n    if(g_isResponsiveViewport.matches == true)\\n    return(false);\\n    \\n    var objMenuItem = jQuery(this);    \\n    var objItem = objMenuItem.find(linkSelector);\\n    \\n    setDisactiveIcon(objItem);     \\n  }\\n  \\n  \\/**\\n  * use this funciton to add active class to all menu item links\\n  *\\/\\n  function onMenuItemMouseover(){    \\n    if(g_isResponsiveViewport.matches == true)\\n    return(false);\\n    \\n    var objHovered = jQuery(this);    \\n    var objItem = objHovered.find(linkSelector);\\n    \\n    g_objMenuItems.removeClass(g_classActive);\\n    objItem.addClass(g_classActive);     \\n  }\\n  \\n  \\/**\\n  * use this funciton to add active class to all menu item links\\n  *\\/\\n  function onMenuItemMouseLeave(){    \\n    if(g_isResponsiveViewport.matches == true)\\n    return(false);\\n    \\n    var objHovered = jQuery(this);    \\n    var objItem = objHovered.find(linkSelector);\\n    \\n    objItem.removeClass(g_classActive);    \\n  }\\n  \\n  function setFirstLevelIcons(){    \\n    if(g_showIcons == false)\\n    return(false);          \\n    \\n    var objFirstLevelMenuLinks = g_objFirstLevelMenuItems.find(linkSelector); \\n    var objFirstLevelExpandIcon = g_objMenu.find(\'.ue-nav-menu-icon-first-level-expand\');\\n    var firstLevelExpandIconHtml = objFirstLevelExpandIcon.html();\\n    var iconWrapperHtml = \\\"<span class=\'ue-nav-menu-icon\'>\\\"+firstLevelExpandIconHtml+\\\"<\\/span>\\\";\\n    \\n    objFirstLevelMenuLinks.append(iconWrapperHtml);\\n    \\n  }\\n  \\n  function setIcons(){    \\n    if(g_showIcons == false)\\n    return(false);\\n    \\n    if(!g_objMenuInnerItems)\\n    return(false);  \\n    \\n    var objMenuLinks = g_objMenuInnerItems.find(linkSelector);  \\n    var iconHtml = \\\"<span class=\'ue-nav-menu-icon\'>\\\"+g_expandIconHtml+\\\"<\\/span>\\\";\\n    \\n    objMenuLinks.append(iconHtml);    \\n  }\\n  \\n  function onBurgerClick(){       \\n    if(dataBehaviour != \\\"slide\\\"){\\n      if(g_objBurger.hasClass(g_classActive) == true){\\n\\n        g_objOpenBurgerIcon.addClass(g_classActive);\\n        g_objCloseBurgerIcon.removeClass(g_classActive);\\n\\n        g_objBurger.removeClass(g_classActive); \\n\\n      }else{\\n\\n        g_objOpenBurgerIcon.removeClass(g_classActive);\\n        g_objCloseBurgerIcon.addClass(g_classActive);\\n\\n        g_objBurger.addClass(g_classActive);      \\n      }\\n    }      \\n    \\n    if(dataBehaviour == \\\"slide\\\"){\\n      var isOpened = g_objMenu.hasClass(openClass);\\n     \\n      if(isOpened == true){\\n        g_objMenu.removeClass(openClass);\\n        g_objMenu.addClass(closeClass);\\n      }else{\\n        g_objMenu.removeClass(closeClass);\\n        g_objMenu.addClass(openClass);\\n      }\\n    } \\n  }\\n  \\n  function onKeyDown(e){\\n    \\n    \\/\\/only on desktop\\n    if(g_isResponsiveViewport.matches == true)\\n    return(true);  \\n    \\n    \\/\\/listen only after \'tab\' key\\n    if(e.keyCode != 9)\\n    return(true);      \\n    \\n    \\/\\/find all \'li\' tags\\n    var objItems = g_objMenu.find(\'li\');  \\n    \\n    \\/\\/set small timeout, so current menu item was mark as focused and triggered\\n    setTimeout(function(){\\n      \\n      \\/\\/look after all menu \'li\' tags\\n      objItems.each(function(){\\n        \\n        var objItem = jQuery(this);      \\n        \\n        \\/\\/if link not focused - skip\\n        if(objItem.find(linkSelector).is(\':focus\') == false)\\n        return(true);            \\n        \\n        var objLink = objItem.find(linkSelector);\\n        var objSubMenu = objLink.next();\\n        \\n        \\/\\/remove active class from others menu items except parent ones    \\n        var objMenuLinksParent = objLink.parents(subMenuSelector).prev();\\n        var objMenuLinksNotParents = g_objMenu.find(\'.ue-menu \'+menuItemSelector+\' \'+subMenuSelector+\' a\').not(objMenuLinksParent);\\n        var objParentsMenuitems = objItem.parents(menuItemSelector);\\n        var objMenuItemsNotParents = objItems.not(objParentsMenuitems);\\n        \\n        var objFirstLevelMenuLinks = jQuery(\'.ue-nav-menu .ue-menu > li \'+linkSelector+\'\');\\n        var isFocusedFirstLevelActiveChildrenLinks = objFirstLevelMenuLinks.next().find(\'li \'+linkSelector).is(\':focus\');\\n        \\n        \\/\\/if there is no expanded menu items inside first level menu items then remove active class      \\n        if(isFocusedFirstLevelActiveChildrenLinks == false)\\n        objFirstLevelMenuLinks.removeClass(g_classActive);     \\n        \\n        objMenuLinksNotParents.removeClass(g_classActive);\\n        objMenuItemsNotParents.removeClass(g_classActive);\\n        \\n        setDisactiveIcon(objMenuLinksNotParents);\\n        \\n        \\/\\/add active class and use css to open sub menu\\n        objItem.addClass(g_classActive);\\t                  \\n        objLink.addClass(g_classActive); \\n        \\n        var objParentMenuItemNum = objLink.parents(menuItemSelector).length;\\n        \\n        if(objParentMenuItemNum > 1)\\n        setActiveIcon(objLink);\\n        \\n      });\\n      \\n    },50)  \\n  }\\n  \\n  \\/**\\n  * close menu on body click\\n  *\\/\\n  function onBodyClick(e){\\n    var objTarget = jQuery(e.target);\\n    var objTargetParents = objTarget.parents();\\n    \\n    \\/\\/if slide and responsive behaviour and close on body click\\n    if(dataBehaviour == \\\"slide\\\" && closeOnBodyClick == true && g_isResponsiveViewport.matches == true){\\n      if(objTargetParents.hasClass(\'ue-nav-menu\') && objTarget.hasClass(\\\"ue-nav-menu_overlay\\\") == false)\\n    \\treturn(true);\\n      \\n      g_objMenuItems.removeClass(g_classActive);\\n      g_objMenuLinks.removeClass(g_classActive);\\n\\n      g_objMenuLinks.each(function(){\\n        setDisactiveIcon(jQuery(this)); \\n      });\\n\\n      var isOpened = g_objMenu.hasClass(openClass);\\n\\n      if(isOpened == true){\\n        g_objMenu.removeClass(openClass);\\n        g_objMenu.addClass(closeClass);\\n      }      \\n    }   \\n    \\n    if(g_isResponsiveViewport.matches == true)\\n    return(true);    \\n\\n    if(objTargetParents.hasClass(\'ue-nav-menu\'))\\n    return(true);\\n    \\n    if(dataBehaviour == \\\"accordion\\\"){\\n      g_objMenuItems.removeClass(g_classActive);\\n      g_objMenuLinks.removeClass(g_classActive);\\n\\n      setDisactiveIcon(g_objMenuLinks); \\n    }    \\n  }\\n     \\n  \\/**\\n  * append back links to submenus\\n  *\\/\\n  function appendBackLinksToSubMenus(){\\n    if(dataBehaviour != \\\"slide\\\")\\n      return(false);\\n    \\n    var objSubMenus = g_objMenu.find(subMenuSelector);\\n    \\n    if(!objSubMenus || objSubMenus.length == 0)\\n      return(false);\\n\\n    var iconHtml;\\n    var backLinkIconClass = \\\"ue-back-link-icon\\\";\\n    var objBackLinkIconPlaceholder = g_objMenu.find(\\\".ue-nav-menu-back-link-icon\\\");\\n\\n    if(!objBackLinkIconPlaceholder || objBackLinkIconPlaceholder.length == 0)\\n      iconHtml = `<span class=\\\"${backLinkIconClass}\\\"><\\/span>`;\\n    else\\n    iconHtml = `<span class=\\\"${backLinkIconClass}\\\">${objBackLinkIconPlaceholder.html()}<\\/span>`;\\n    \\n    objSubMenus.each(function(){\\n      var objSubMenu = jQuery(this);\\n      var backLinkHtml = `<li class=\\\"${backLinkClass}\\\"><a href=\\\"javascript:void(0);\\\">{{back_link_text|raw}} ${iconHtml}<\\/a><\\/li>`;\\n      \\n      objSubMenu.prepend(backLinkHtml);\\n    });\\n  }\\n  \\n  \\/**\\n  * on back link click\\n  *\\/\\n  function onBackLinkClick(e){\\n    var objBackLink = jQuery(this);\\n    var objParentSubMenu = objBackLink.closest(subMenuSelector);\\n    var objMenuLink = objParentSubMenu.prev();\\n    \\n    onMenuLinkClick(e, objMenuLink);\\n  }\\n     \\n  \\/**\\n  * on side menu close\\n  *\\/\\n  function onSideMenuClose(){\\n    g_objMenuItems.removeClass(g_classActive);\\n    g_objMenuLinks.removeClass(g_classActive);\\n\\n    g_objMenuLinks.each(function(){\\n      setDisactiveIcon(jQuery(this)); \\n    });\\n       \\n    \\n    var isOpened = g_objMenu.hasClass(openClass);\\n     \\n    if(isOpened == true){\\n      g_objMenu.removeClass(openClass);\\n      g_objMenu.addClass(closeClass);\\n    }else{\\n      g_objMenu.removeClass(closeClass);\\n      g_objMenu.addClass(openClass);\\n    }\\n  }\\n  \\n  \\/**\\n  * init menu layout\\n  *\\/\\n  function initMenuLayout(){\\n    var objSubMenus = g_objMenu.find(subMenuSelector);\\n    \\n    if(!objSubMenus || objSubMenus.length == 0)\\n      return(false);\\n    \\n    objSubMenus.each(function(){\\n      var objSubMenu = jQuery(this);\\n      var objParentLink = objSubMenu.prev();\\n      \\n      if(clickableParents == false)\\n        objParentLink.attr(\\\"href\\\", \\\"javascript:void(0);\\\")\\n      \\n    });\\n    \\n    var objIconsHolder = g_objMenu.find(\\\".ue-nav-menu-icons-holder\\\");\\n    \\n    \\/\\/objIconsHolder.remove();\\n  }\\n  \\n  appendBackLinksToSubMenus();\\n  setFirstLevelIcons();\\n  setIcons();\\n  initResponsiveMode(false);\\n  setHoverEffects();\\n  initMenuLayout();\\n  \\n  \\/\\/init events\\n  jQuery(window).on(\'resize\', function(){\\n  \\tinitResponsiveMode(true);\\n  });\\n  \\n  g_objMenuLinks.on(\'click\', function(e){\\n    var objLink = jQuery(this);\\n    onMenuLinkClick(e, objLink);\\n  });\\n     \\n  \\/\\/on back link click\\n  jQuery(`.${backLinkClass}`).on(\\\"click\\\", onBackLinkClick);\\n  \\n  g_objBurger.on(\'click\', onBurgerClick)