INSERT INTO `wpfd_addonlibrary_addons` (`id`, `title`, `name`, `alias`, `addontype`, `description`, `ordering`, `templates`, `config`, `catid`, `is_active`, `test_slot1`, `test_slot2`, `test_slot3`) VALUES
(7, 'Woo Mini Cart', 'woo_mini_cart_ax_elementor', 'woo_mini_cart_ax', 'elementor', 'The Woo Mini Cart widget for Elementor enhances the shopping experience by allowing users to view cart items and proceed to checkout without leaving the current page.', 3, '{\"html\":\"{% set url_cart = ucfunc(\\\"get_woo_endpoint\\\",\\\"cart\\\") %}\\n{% set url_checkout = ucfunc(\\\"get_woo_endpoint\\\",\\\"checkout\\\") %}\\n\\n<div id=\\\"{{uc_id}}\\\" class=\\\"ue-mini-cart_wrapper\\\">\\n <div id=\\\"{{uc_id}}\\\" class=\\\"ue-mini-cart_container\\\">\\n   \\n  {% if show_toggle_button == \\\"true\\\" %}\\n    <div class=\\\"ue_mini_cart_toggle\\\">\\n      {% if show_toggle_icon == \\\"true\\\" %}{{toggle_icon_html|raw}}{% endif %}{{toggle_text}}\\n      {% if show_cart_total_in_toggle == \\\"true\\\" %}<div class=\\\"uc-mini-cart-toggle-subtotal\\\">{{ucfunc(\\\"put_woo_cart_html\\\",\\\"total2\\\")}}<\\/div>{% endif %}\\n      {% if show_products_count == \\\"true\\\" %}<div class=\\\"ue-product-count\\\">{{ucfunc(\\\"put_woo_cart_html\\\",\\\"num_products\\\")}}<\\/div>{% endif %}\\n    <\\/div>\\n  {% endif %}\\n\\n  <div id=\\\"{{uc_id}}\\\" class=\\\"ue-mini-cart\\\" {% if show_toggle_button == \\\"true\\\" %}style=\\\"display:none;\\\"{% endif %}>\\n    <div class=\\\"ue_cart_header\\\">\\n      {% if show_cart_title == \\\"true\\\" %}<div class=\\\"ue-mini-cart-title\\\">{{cart_title|raw}}<\\/div>{% endif %}\\n      {% if show_cart_close_button == \\\"true\\\" %}<div class=\\\"ue_cart_close_button\\\">{{cart_close_button_html|raw}}<\\/div>{% endif %}\\n    <\\/div>\\n\\n      {{ucfunc(\\\"put_woo_cart_html\\\",\\\"items\\\")}}\\n\\n    <div class=\\\"ue-mini-cart-footer\\\">\\n\\n      <div class=\\\"ue-mini-cart-empty-message\\\">{{empty_message_text|raw}}<\\/div>\\n      {% if show_subtotal == \\\"true\\\" %}\\n        <div class=\\\"ue-mini-cart-subtotal\\\">{{show_text|raw}}\\n          {% if fill_gap_with_dashes == \\\"true\\\" %}<span class=\\\"ue-total-gap-dots\\\"><\\/span>{% endif %}\\n          <div class=\\\"ue_subtotal_amount\\\">\\n              {{ucfunc(\\\"put_woo_cart_html\\\",\\\"total\\\")}}\\n           <\\/div>\\n        <\\/div>\\n      {% endif %}\\n\\n      <div class=\\\"ue_cart_btn_wrapper\\\">\\n         {% if show_cart_button == \\\"true\\\" %}<a href=\\\"{{url_cart}}\\\" class=\\\"ue-mini-cart-viewcart-btn\\\">{{cart_button_text|raw}}<\\/a>{% endif %}\\n         {% if show_checkout_button == \\\"true\\\" %}<a href=\\\"{{url_checkout}}\\\" class=\\\"ue-mini-cart-checkout-btn\\\" data-hide=\\\"{{hide_checkout_button_cart_empty}}\\\">{{checkout_button_text|raw}}<\\/a>{% endif %}\\n      <\\/div>\\n    <\\/div>\\n  <\\/div>\\n   \\n <\\/div>\\n<\\/div>\",\"css\":\"#{{uc_id}} .ue-mini-cart_container{\\n   display: flex;\\n   flex-direction: row;\\n   position: relative;\\n}\\n#{{uc_id}} .ue-mini-cart{\\n  display:flex;\\n  flex-direction:column;\\n  overflow:hidden;\\n  {% if show_toggle_button == \\\"true\\\" %}\\n   position:absolute;\\n   z-index:99999;\\n  {% endif %}\\n}\\n#{{uc_id}} .ue_mini_cart_toggle{\\n  transition: 200ms all;\\n}\\n#{{uc_id}} .ue-mini-cart-empty-message{\\n\\tdisplay: none;\\n}\\n\\n#{{uc_id}} .ue-mini-cart-item{\\n  transition: all .3s;\\n}\\n\\n#{{uc_id}} .ue-mini-cart-item.ue-loading{\\n\\topacity: .5;\\n}\\n\\n{% if show_toggle_button == \\\"true\\\" %}\\n#{{uc_id}} .ue_mini_cart_toggle{\\n  display: inline-flex;\\n  gap: 6px;\\n  align-items: center;\\n  cursor:pointer;\\n}\\n{% endif %}\\n\\n#{{uc_id}} .ue_cart_header{\\n  display:flex;\\n  justify-content: space-between;\\n  align-items: center;\\n}\\n\\n{% if show_cart_close_button == \\\"true\\\" %}\\n#{{uc_id}} .ue_cart_close_button{\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  cursor:pointer;\\n  overflow:hidden;\\n}\\n#{{uc_id}} .ue_cart_close_button svg{\\n  width:1em;\\n  height:1em;\\n}\\n{% endif %}\\n\\n#{{uc_id}} .ue-mini-cart-items-holder{\\n  display: flex;\\n  flex-direction: column;\\n  overflow-y:scroll;\\n  transition: all .3s;\\n}\\n\\n#{{uc_id}} .ue-mini-cart-item\\n{\\n  display:flex;\\n  align-items:center;\\n  transition: all .3s;\\n}\\n\\n#{{uc_id}} .ue-mini-cart-item-content\\n{\\n  display:flex;\\n  flex-grow:1;\\n  align-self: stretch;\\n}\\n\\n#{{uc_id}} .ue-mini-cart-content-wrapper\\n{\\n  display:block;\\n  flex-grow:1;\\n}\\n\\n#{{uc_id}} .ue-mini-cart-item-title-text\\n{\\n  flex-grow:1;\\n}\\n#{{uc_id}} .ue_mini_price{\\n  display:inline-flex;\\n  align-items: center;\\n}\\n\\n{% if show_remove_product_button == \\\"true\\\" %}\\n#{{uc_id}} .ue-mini-cart-item-delete\\n{\\n  display:flex;\\n  align-items:center;\\n  flex-grow:0;\\n  flex-shrink:0;\\n  cursor:pointer;\\n}\\n#{{uc_id}} .ue-mini-cart-item-delete svg{\\n  width:1em;\\n  height:1em;\\n}\\n#{{uc_id}} .ue-mini-cart-item-delete i{\\n  width:1em;\\n  height:1em;\\n  display:flex;\\n  align-content: center;\\n  justify-content: center;\\n}\\n.ue-mini-cart-item-delete {\\n  font-size:12px;\\n  line-height:1;\\n}\\n\\n{% endif %}\\n\\n#{{uc_id}} .ue-mini-cart-footer\\n{\\n  margin-top:auto;\\n}\\n{% if show_subtotal == \\\"true\\\" %}\\n#{{uc_id}} .ue-mini-cart-subtotal{\\n  display: flex;\\n  width: 100%;\\n  \\/* align-items: center; *\\/\\n  align-items: baseline;\\n  position:relative;\\n}\\n  {% if fill_gap_with_dashes == \\\"true\\\" %}\\n  #{{uc_id}} .ue-total-gap-dots{\\n    border-bottom: 1px dashed {{subtotal_text_color}};\\n    flex-grow: 1;\\n  }\\n  {% endif %}\\n{% endif %}\\n\\n#{{uc_id}} .ue_cart_btn_wrapper\\n{\\n  display: flex;\\n}\\n\\n{% if show_product_quantity_input == \\\"true\\\" %}\\n#{{uc_id}} .ue_mini_quantity_input{\\n  display:inline-flex;\\n  background: #fff;\\n  border-radius: 4px;\\n  border: 1px solid #ddd;\\n}\\n#{{uc_id}} .ue_mini_minus,\\n#{{uc_id}} .ue_mini_plus {\\n  display:inline-flex;\\n  justify-content: center;\\n  align-items: center;\\n  text-align: center;\\n  cursor: pointer;\\n  user-select: none;\\n  -moz-user-sel