nit\":\"%\",\"size\":40},\"_id\":\"4809c1b\"},{\"layer_position_vr\":{\"unit\":\"%\",\"size\":60},\"layer_position_hr\":{\"unit\":\"%\",\"size\":20},\"_id\":\"951e42b\"}]},\"elements\":[{\"id\":\"1211f24\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"https:\\/\\/www.graodelivery.online\\/wp-content\\/uploads\\/2025\\/12\\/IMG1.png\",\"id\":50,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"medium_large\"},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true}],\"isInner\":false}]'),
