(285, 1, '2025-12-05 21:41:03', '2025-12-05 21:41:03', '<!-- start Woo Product Grid -->\n		<link id=\'font-awesome-css\' href=\'https://www.graodelivery.online/wp-content/plugins/unlimited-elements-for-elementor/assets_libraries/font-awesome6/fontawesome-all.min.css\' type=\'text/css\' rel=\'stylesheet\' >\n		<link id=\'font-awesome-4-shim-css\' href=\'https://www.graodelivery.online/wp-content/plugins/unlimited-elements-for-elementor/assets_libraries/font-awesome6/fontawesome-v4-shims.min.css\' type=\'text/css\' rel=\'stylesheet\' >\n<style>/* widget: Woo Product Grid */\n#uc_woocommerce_product_grid_elementor_42c6714 * {\n	-webkit-box-sizing: border-box;\n	-moz-box-sizing: border-box;\n	box-sizing: border-box;    \n}\n#uc_woocommerce_product_grid_elementor_42c6714 .ue_woocommerce_product_label-custom-field{\n	z-index: 100;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .ue_category_wrapper{\n  display: flex;\n  flex-wrap: wrap;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_post_grid_style_one_item{\n	transition: all.3s;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 span.add-to-cart__loader{\n  	position: absolute;\n  	right: 0;\n  	top: 50%;\n  	transform: translate(0, -50%);\n  	line-height: 1em;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .add_to_cart_button.loading span.add-to-cart__loader{\n	display: inline-block !important;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc-grid-count-buttons{\n	display: flex;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc-grid-count-buttons button{\n	display: flex;\n    align-items:center;\n    justify-content:center;\n    flex-grow:0;\n    flex-shrink:0;\n    line-height:1em;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc-grid-count-buttons button:disabled{\n	opacity:0.5;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_more_btn-custom-field{\n  text-align:center;\n  text-decoration:none;\n  transition:0.3s;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc-grid-count-buttons button svg{\n	height:1em;\n    width:1em;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 input.uc-grid-count-buttons__number{\n  text-align:center;\n  flex-grow:1;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 {\n  margin:0 auto;\n  position:relative;  \n}\n.uc_post_grid_style_one .uc_post_grid_style_one_item {\n	color: #111;\n	font-size: 16px;\n	overflow: hidden;\n  	position: relative;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_post_grid_style_one_image {\n	width: 100%;\n	overflow: hidden;\n	display: block;\n  	position: relative;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_post_image {\n    position:relative;\n	display: block;\n	transition: all 0.25s ease-in-out;\n    overflow:hidden;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_post_image--second{\n  	width: 100%;\n    height: 100%;\n    object-fit: cover;\n	position: absolute;\n  	top: 0;\n  	right: 0;\n  	  		  			transform: translate(100%, 0);\n  	transition: all .3s;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_post_grid_style_one_image:hover .uc_post_image--second{  \n  			transform: translate(0, 0);\n  	}\n#uc_woocommerce_product_grid_elementor_42c6714  .uc_post_image img\n{\n  width:100%;\n  display: block;\n  transition:0.3s;\n}\n.uc_post_grid_style_one .uc_title {\n    font-size: 21px;   \n}\n.uc_post_grid_style_one .uc_title a {\n	text-decoration: none;\n   transition: all .3s ease;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_post_grid_style_one_button > button,\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_more_btn-custom-field{\n	width: 100%;\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_post_grid_style_one_button > a,\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_post_grid_style_one_button > button,\n#uc_woocommerce_product_grid_elementor_42c6714 .uc-button-addcart,\n#uc_woocommerce_product_grid_elementor_42c6714 .added_to_cart,\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_more_btn-custom-field{\n	display: block;\n	text-align: center;\n    text-decoration: none;\n    text-transform: none;\n	transition: all 0.25s ease-in-out;\n    vertical-align: middle;\n}\n  #uc_woocommerce_product_grid_elementor_42c6714 .uc-button-addcart.added{\n    display:none;\n  }\n#uc_woocommerce_product_grid_elementor_42c6714.uc_post_grid_style_one .uc_post_grid_style_one_wrap {	\n    display: grid;\n}\n    #uc_woocommerce_product_grid_elementor_42c6714.uc_post_grid_style_one .uc_content{\n      flex-grow: 1;\n      display: flex;\n      flex-flow: column nowrap;\n    }\n    #uc_woocommerce_product_grid_elementor_42c6714 .ue_grid_item_bottom    {\n      margin-top:auto;\n    }\n  .uc_post_grid_style_one .uc_post_grid_style_one_item {\n      flex-direction:column;\n      display:flex;\n  }\n@media (max-width:1023px){\n	#uc_woocommerce_product_grid_elementor_42c6714.uc_post_grid_style_one .uc_post_grid_style_one_wrap {\n		grid-template-columns: repeat(2, 1fr);\n	}\n}\n@media (max-width:639px){\n	#uc_woocommerce_product_grid_elementor_42c6714.uc_post_grid_style_one .uc_post_grid_style_one_wrap {\n		grid-template-columns: repeat(1, 1fr);\n	}\n}\n#uc_woocommerce_product_grid_elementor_42c6714 .ue_category_label{\n  display:block;\n  text-decoration:none;\n  transition: all .3s ease;\n  position: relative;\n}\n/* hide default arrows in input type number */\n/* Chrome, Safari, Edge, Opera */\n#uc_woocommerce_product_grid_elementor_42c6714 input.uc-grid-count-buttons__number::-webkit-outer-spin-button,\n#uc_woocommerce_product_grid_elementor_42c6714 input.uc-grid-count-buttons__number::-webkit-inner-spin-button{\n	-webkit-appearance: none;\n  	margin: 0;\n}\n/* Firefox */\n#uc_woocommerce_product_grid_elementor_42c6714 input.uc-grid-count-buttons__number[type=number]{\n	-moz-appearance: textfield;\n}\n/* end hide default arrows in input type number */\n#uc_woocommerce_product_grid_elementor_42c6714 .uc_regular_price:not(.uc_regular_price--single){\n  text-decoration:line-through !important;\n}\n