(388, 1, '2025-12-05 23:49:20', '2025-12-05 23:49:20', '<a href=\"https://graodelivery.online\">\n							<img width=\"279\" height=\"127\" src=\"https://www.graodelivery.online/wp-content/uploads/2025/12/Logo1.png\" alt=\"\" />								</a>\n<!-- start WordPress Menu -->\n		<link id=\'font-awesome-css\' href=\'https://www.graodelivery.online/wp-content/plugins/unlimited-elements-for-elementor/assets_libraries/font-awesome6/fontawesome-all.min.css\' type=\'text/css\' rel=\'stylesheet\' >\n		<link id=\'font-awesome-4-shim-css\' href=\'https://www.graodelivery.online/wp-content/plugins/unlimited-elements-for-elementor/assets_libraries/font-awesome6/fontawesome-v4-shims.min.css\' type=\'text/css\' rel=\'stylesheet\' >\n		<link id=\'uc_ac_assets_file_uc_creative_link_effects_css_26314-css\' href=\'https://www.graodelivery.online/wp-content/uploads/ac_assets/nav_menu/uc-creative-link-effects.css\' type=\'text/css\' rel=\'stylesheet\' >\n<style>/* widget: WordPress Menu */\n/* reset defaults */\ndd, dl, dt, li, ol, ul{\n  border: unset;\n  padding: unset;\n  background: unset;\n}\n/* end reset defaults */\n#uc_nav_menu_elementor_9ff4970{\n	position: relative;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-nav-menu-mobile-wrapper{\n 	display: flex;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-menu{\n    display:flex;\n    list-style:none;\n    margin:0;\n    position:relative;\n  	justify-content:flex-end;\n}\n#uc_nav_menu_elementor_9ff4970 a{\n  	position: relative;\n	text-decoration: none;\n 	display: flex;\n  	align-items: center;  \n}\n#uc_nav_menu_elementor_9ff4970 .ue-menu > li {\n	display: block;\n  	       flex-shrink: 1;\n   	   min-width: 0;\n  	}\n/* Simple multilevel dropdown */\n#uc_nav_menu_elementor_9ff4970 .ue-menu > li > .sub-menu {\n	opacity: 0;\n	visibility: hidden;\n	position: absolute;\n	list-style: none;\n	text-align: inherit;\n    display:block;\n	z-index: 99;\n}\n/* First level appear */\n#uc_nav_menu_elementor_9ff4970 .ue-menu > li:hover > .sub-menu{\n	opacity: 1;\n	visibility: visible;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-menu > li.uc-active > .sub-menu {\n	opacity: 1;\n	visibility: visible;\n}\n/* Style for dropdown links */\n#uc_nav_menu_elementor_9ff4970 .ue-menu li > .sub-menu li {\n	position: relative;\n	display: block;\n}\n/* Second and third dropdown level */\n#uc_nav_menu_elementor_9ff4970 .ue-menu > li > .sub-menu li{\n  display: block;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-menu > li > .sub-menu > li .sub-menu {\n	opacity: 0;\n	visibility: hidden;\n	position: absolute;\n	list-style: none;\n	top:0px;\n  	z-index: 100;\n}\n/* Second and third level appears */\n#uc_nav_menu_elementor_9ff4970 .ue-menu > li .sub-menu li:hover > .sub-menu {\n	opacity: 1;\n	visibility: visible;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-menu > li .sub-menu li.uc-active > .sub-menu {\n	opacity: 1;\n	visibility: visible;\n}\n#uc_nav_menu_elementor_9ff4970 li,\n#uc_nav_menu_elementor_9ff4970 a{\n	transition: all 0.3s ease-in-out;\n}\n#uc_nav_menu_elementor_9ff4970 ul{\n	transition: all 0.3s ease-in-out;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-nav-menu-checkbox{ \n  	display: none; \n}\n#uc_nav_menu_elementor_9ff4970 .ue-nav-menu-mobile{\n  	display: none;\n	transition: all .3s;\n    cursor: pointer;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-nav-menu-icon,\n#uc_nav_menu_elementor_9ff4970 .ue-back-link-icon{\n	display: flex;\n    transition: all .3s ease;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-nav-menu-icon i {\n  pointer-events: none;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-back-link{\n  display: none !important;\n}\n#uc_nav_menu_elementor_9ff4970 .uc-close-side-menu{\n  display: none;\n  transition: all .3s ease;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-nav-menu-mobile > *{\n	display: none;\n  	justify-content: center;\n  	align-items: center;\n}\n#uc_nav_menu_elementor_9ff4970 .ue-nav-menu-mobile > .uc-active{\n	display: flex;\n}\n/* hover effects */\n/*Effect 1*/\n#uc_nav_menu_elementor_9ff4970 .uc_cl-effect-1 a:hover::before, \n#uc_nav_menu_elementor_9ff4970 .uc_cl-effect-1 a:hover::after, \n#uc_nav_menu_elementor_9ff4970 .uc_cl-effect-1 a:focus::before, \n#uc_nav_menu_elementor_9ff4970 .uc_cl-effect-1 a:focus::after, \n#uc_nav_menu_elementor_9ff4970 .uc_cl-effect-1 a.active::before, \n#uc_nav_menu_elementor_9ff4970 .uc_cl-effect-1 a.active::after{\n  color: ;\n}\n/* end hover effects */\n@media only screen and (max-width: 1024px) {\n      #uc_nav_menu_elementor_9ff4970 .ue-menu{\n          justify-content:;\n      }\n      }\n@media only screen and (max-width: 767px) {\n  	 #uc_nav_menu_elementor_9ff4970 .ue-menu{\n          justify-content:;\n     }\n     }\n@media only screen and (max-width: 767px) {\n	#uc_nav_menu_elementor_9ff4970 .ue-menu {	\n      	transition: all .3s;\n      	flex-direction: column;      	\n      	top: 100%;\n      	left: 0;\n      	z-index: 1000;\n    }\n    #uc_nav_menu_elementor_9ff4970 .sub-menu{\n      	visibility: visible !important;\n      	opacity: 1 !important;\n      	inset-inline-start: unset !important;\n        transition-timing-function: ease;\n    } 	\n	#uc_nav_menu_elementor_9ff4970 .ue-nav-menu-mobile {\n        position: relative;\n        display: flex;\n        align-items:center;\n        justify-content:center;      \n	}\n	#uc_nav_menu_elementor_9ff4970 .ue-nav-menu-checkbox:checked + .ue-menu {\n		opacity: 1;\n      	pointer-events: all;\n	} \n    /* open sub menus from side */\n          #uc_nav_menu_elementor_9ff4970 .ue-menu{\n        width: 100%;\n        position: absolute;\n        transform: translate(0, -20px);\n     	opacity: 0; \n      	pointer-events: none;\n      }\n      #uc_nav_menu_elementor_9ff4970 .ue-nav-menu-checkbox:checked + .ue-menu {\n          transform: translate(0, px);\n      } \n      #uc_nav_menu_elementor_9ff4970 .ue-menu > li > .sub-menu {\n          width: 100%;\n          position:relative;\n          top:auto;\n      }\n      #uc_nav_menu_elementor_9ff4970 .ue-menu > li > .sub-menu > li .sub-menu {\n          width: 100%;\n   