: 1;\n	visibility: visible;\n}\n#uc_nav_menu_elementor_246fba4 .ue-menu > li.uc-active > .sub-menu {\n	opacity: 1;\n	visibility: visible;\n}\n/* Style for dropdown links */\n#uc_nav_menu_elementor_246fba4 .ue-menu li > .sub-menu li {\n	position: relative;\n	display: block;\n}\n/* Second and third dropdown level */\n#uc_nav_menu_elementor_246fba4 .ue-menu > li > .sub-menu li{\n  display: block;\n}\n#uc_nav_menu_elementor_246fba4 .ue-menu > li > .sub-menu > li .sub-menu {\n	opacity: 0;\n	visibility: hidden;\n	position: absolute;\n	list-style: none;\n	top:0px;\n  	z-index: 100;\n}\n/* Second and third level appears */\n#uc_nav_menu_elementor_246fba4 .ue-menu > li .sub-menu li:hover > .sub-menu {\n	opacity: 1;\n	visibility: visible;\n}\n#uc_nav_menu_elementor_246fba4 .ue-menu > li .sub-menu li.uc-active > .sub-menu {\n	opacity: 1;\n	visibility: visible;\n}\n#uc_nav_menu_elementor_246fba4 li,\n#uc_nav_menu_elementor_246fba4 a{\n	transition: all 0.3s ease-in-out;\n}\n#uc_nav_menu_elementor_246fba4 ul{\n	transition: all 0.3s ease-in-out;\n}\n#uc_nav_menu_elementor_246fba4 .ue-nav-menu-checkbox{ \n  	display: none; \n}\n#uc_nav_menu_elementor_246fba4 .ue-nav-menu-mobile{\n  	display: none;\n	transition: all .3s;\n    cursor: pointer;\n}\n#uc_nav_menu_elementor_246fba4 .ue-nav-menu-icon,\n#uc_nav_menu_elementor_246fba4 .ue-back-link-icon{\n	display: flex;\n    transition: all .3s ease;\n}\n#uc_nav_menu_elementor_246fba4 .ue-nav-menu-icon i {\n  pointer-events: none;\n}\n#uc_nav_menu_elementor_246fba4 .ue-back-link{\n  display: none !important;\n}\n#uc_nav_menu_elementor_246fba4 .uc-close-side-menu{\n  display: none;\n  transition: all .3s ease;\n}\n#uc_nav_menu_elementor_246fba4 .ue-nav-menu-mobile > *{\n	display: none;\n  	justify-content: center;\n  	align-items: center;\n}\n#uc_nav_menu_elementor_246fba4 .ue-nav-menu-mobile > .uc-active{\n	display: flex;\n}\n/* hover effects */\n/*Effect 1*/\n#uc_nav_menu_elementor_246fba4 .uc_cl-effect-1 a:hover::before, \n#uc_nav_menu_e